import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

// Actuator mac dinh chi expose /health va /info; can bat them cac endpoint
// khac qua management.endpoints.web.exposure.include neu can (vi du /metrics,/loggers).
@Component
class PaymentGatewayHealthIndicator implements HealthIndicator {

    @Override
    public Health health() {
        boolean reachable = pingPaymentGateway();
        if (reachable) {
            return Health.up().withDetail("paymentGateway", "reachable").build();
        }
        return Health.down().withDetail("paymentGateway", "unreachable").build();
    }

    private boolean pingPaymentGateway() {
        return true;
    }
}

